objinit.implementation:
chDbgCheck((size <= (size_t)INT_MAX) && ((size == 0U) || (nodes != NULL)));

#if VFS_CFG_ENABLE_DRV_ROOT == TRUE
self->root = NULL;
#endif
self->nodes = nodes;
self->size = size;
if (size > 0U) {
  memset(nodes, 0, size * sizeof *nodes);
}

method.implementation:
msg_t ret;
size_t i;

ret = check_node(np);
if (CH_RET_IS_ERROR(ret)) {
  return (int)ret;
}

chSysLock();
for (i = 0U; i < self->size; i++) {
  if (self->nodes[i] == NULL) {
    self->nodes[i] = np;
    chSysUnlock();
    return (int)i;
  }
}
chSysUnlock();

return CH_RET_EMFILE;

msg_t ret;

if ((fd < 0) || ((size_t)fd >= self->size)) {
  return CH_RET_EBADF;
}
ret = check_node(np);
if (CH_RET_IS_ERROR(ret)) {
  return ret;
}

chSysLock();
if (self->nodes[fd] != NULL) {
  ret = CH_RET_EBUSY;
}
else {
  self->nodes[fd] = np;
}
chSysUnlock();

return ret;

vfs_node_c *np;

if (CH_RET_IS_ERROR(pin_descriptor(self, fd, &np))) {
  return NULL;
}

return np;

vfs_node_c *np;

if ((fd < 0) || ((size_t)fd >= self->size)) {
  return CH_RET_EBADF;
}

chSysLock();
np = self->nodes[fd];
if (!is_node(np)) {
  chSysUnlock();
  return CH_RET_EBADF;
}
self->nodes[fd] = NULL;
chSysUnlock();
(void)roRelease(np);

return CH_RET_SUCCESS;

vfs_node_c *np;
size_t i;
int ret;

if ((fd < 0) || ((size_t)fd >= self->size)) {
  return CH_RET_EBADF;
}

chSysLock();
np = self->nodes[fd];
ret = CH_RET_EBADF;
if (is_node(np)) {
  ret = CH_RET_EMFILE;
  for (i = 0U; i < self->size; i++) {
    if (self->nodes[i] == NULL) {
      if (retain_nodeI(np)) {
        self->nodes[i] = np;
        ret = (int)i;
      }
      else {
        ret = CH_RET_EOVERFLOW;
      }
      break;
    }
  }
}
chSysUnlock();

return ret;

vfs_node_c *np, *displaced = NULL;
int ret;

if ((oldfd < 0) || ((size_t)oldfd >= self->size) ||
    (newfd < 0) || ((size_t)newfd >= self->size)) {
  return CH_RET_EBADF;
}

chSysLock();
np = self->nodes[oldfd];
ret = CH_RET_EBADF;
if (is_node(np)) {
  ret = newfd;
  if (oldfd != newfd) {
#if VFS_CFG_ENABLE_DRV_ROOT == TRUE
    if (self->nodes[newfd] == &reserved_node) {
      chSysUnlock();
      return CH_RET_EBUSY;
    }
#endif
    if (retain_nodeI(np)) {
      displaced = self->nodes[newfd];
      self->nodes[newfd] = np;
    }
    else {
      ret = CH_RET_EOVERFLOW;
    }
  }
}
chSysUnlock();
if (displaced != NULL) {
  (void)roRelease(displaced);
}

return ret;

size_t i;

for (i = 0U; i < self->size; i++) {
#if VFS_CFG_ENABLE_DRV_ROOT == TRUE
  chDbgAssert(self->nodes[i] != &reserved_node, "active open");
#endif
  (void)vfsIOClose(self, (int)i);
}

vfs_node_c *np;
ssize_t ret;

ret = pin_descriptor(self, fd, &np);
if (CH_RET_IS_ERROR(ret)) {
  return ret;
}
if (VFS_MODE_S_ISDIR(np->mode)) {
  ret = CH_RET_EISDIR;
}
else if (n == 0U) {
  ret = 0;
}
else if (buf == NULL) {
  ret = CH_RET_EINVAL;
}
else {
  ret = vfsFileRead((vfs_file_node_c *)np, buf, n);
}
(void)roRelease(np);

return ret;

vfs_node_c *np;
ssize_t ret;

ret = pin_descriptor(self, fd, &np);
if (CH_RET_IS_ERROR(ret)) {
  return ret;
}
if (VFS_MODE_S_ISDIR(np->mode)) {
  ret = CH_RET_EISDIR;
}
else if (n == 0U) {
  ret = 0;
}
else if (buf == NULL) {
  ret = CH_RET_EINVAL;
}
else {
  ret = vfsFileWrite((vfs_file_node_c *)np, buf, n);
}
(void)roRelease(np);

return ret;

vfs_node_c *np;
msg_t ret;

if (sp == NULL) {
  return CH_RET_EINVAL;
}
ret = pin_descriptor(self, fd, &np);
if (CH_RET_IS_ERROR(ret)) {
  return ret;
}
ret = vfsNodeStat(np, sp);
(void)roRelease(np);

return ret;

vfs_node_c *np;
vfs_offset_t ret;

if ((whence != VFS_SEEK_SET) && (whence != VFS_SEEK_CUR) &&
    (whence != VFS_SEEK_END)) {
  return CH_RET_EINVAL;
}
ret = pin_descriptor(self, fd, &np);
if (CH_RET_IS_ERROR(ret)) {
  return ret;
}
if (VFS_MODE_S_ISDIR(np->mode)) {
  ret = CH_RET_EISDIR;
}
else if (!VFS_MODE_S_ISREG(np->mode)) {
  ret = CH_RET_ESPIPE;
}
else {
  ret = vfsFileSetPosition((vfs_file_node_c *)np, offset, whence);
  if (!CH_RET_IS_ERROR(ret)) {
    ret = vfsFileGetPosition((vfs_file_node_c *)np);
  }
}
(void)roRelease(np);

return ret;

vfs_node_c *np;
vfs_offset_t ret;

ret = pin_descriptor(self, fd, &np);
if (CH_RET_IS_ERROR(ret)) {
  return ret;
}
if (VFS_MODE_S_ISDIR(np->mode)) {
  ret = CH_RET_EISDIR;
}
else if (!VFS_MODE_S_ISREG(np->mode)) {
  ret = CH_RET_ESPIPE;
}
else {
  ret = vfsFileGetPosition((vfs_file_node_c *)np);
}
(void)roRelease(np);

return ret;

vfs_node_c *np;
msg_t ret;

if (dip == NULL) {
  return CH_RET_EINVAL;
}
ret = pin_descriptor(self, fd, &np);
if (CH_RET_IS_ERROR(ret)) {
  return ret;
}
if (!VFS_MODE_S_ISDIR(np->mode)) {
  ret = CH_RET_ENOTDIR;
}
else {
  ret = vfsDirReadFirst((vfs_directory_node_c *)np, dip);
}
(void)roRelease(np);

return ret;

vfs_node_c *np;
msg_t ret;

if (dip == NULL) {
  return CH_RET_EINVAL;
}
ret = pin_descriptor(self, fd, &np);
if (CH_RET_IS_ERROR(ret)) {
  return ret;
}
if (!VFS_MODE_S_ISDIR(np->mode)) {
  ret = CH_RET_ENOTDIR;
}
else {
  ret = vfsDirReadNext((vfs_directory_node_c *)np, dip);
}
(void)roRelease(np);

return ret;

vfs_node_c *np;
msg_t ret;

ret = pin_descriptor(self, fd, &np);
if (CH_RET_IS_ERROR(ret)) {
  return ret;
}
if (VFS_MODE_S_ISDIR(np->mode)) {
  ret = CH_RET_EISDIR;
}
else {
  ret = vfsFileControl((vfs_file_node_c *)np, operation, arg);
}
(void)roRelease(np);

return ret;

vfs_node_c *np = NULL;
size_t i;
msg_t ret;

if (self->root == NULL) {
  return CH_RET_ENOSYS;
}
if (path == NULL) {
  return CH_RET_EINVAL;
}

/* Reserve before driver calls, including create or truncate side effects.*/
chSysLock();
for (i = 0U; i < self->size; i++) {
  if (self->nodes[i] == NULL) {
    self->nodes[i] = &reserved_node;
    break;
  }
}
chSysUnlock();
if (i == self->size) {
  return CH_RET_EMFILE;
}

ret = vfsRootOpen(self->root, path, flags, &np);
if (CH_RET_IS_ERROR(ret)) {
  /* Failed opens do not transfer a node reference.*/
  np = NULL;
}
else {
  ret = check_node(np);
}
chSysLock();
chDbgAssert(self->nodes[i] == &reserved_node, "lost reservation");
self->nodes[i] = CH_RET_IS_ERROR(ret) ? NULL : np;
chSysUnlock();
if (CH_RET_IS_ERROR(ret)) {
  if (np != NULL) {
    (void)roRelease(np);
  }
  return (int)ret;
}

return (int)i;

if (self->root == NULL) {
  return CH_RET_ENOSYS;
}
if ((path == NULL) || (sp == NULL)) {
  return CH_RET_EINVAL;
}

return vfsFSStat(self->root, path, sp);

if (self->root == NULL) {
  return CH_RET_ENOSYS;
}
if (path == NULL) {
  return CH_RET_EINVAL;
}

return vfsFSUnlink(self->root, path);

if (self->root == NULL) {
  return CH_RET_ENOSYS;
}
if ((oldpath == NULL) || (newpath == NULL)) {
  return CH_RET_EINVAL;
}

return vfsFSRename(self->root, oldpath, newpath);

if (self->root == NULL) {
  return CH_RET_ENOSYS;
}
if (path == NULL) {
  return CH_RET_EINVAL;
}

return vfsFSMkdir(self->root, path, mode);

if (self->root == NULL) {
  return CH_RET_ENOSYS;
}
if (path == NULL) {
  return CH_RET_EINVAL;
}

return vfsFSRmdir(self->root, path);

if (self->root == NULL) {
  return CH_RET_ENOSYS;
}
if (path == NULL) {
  return CH_RET_EINVAL;
}

return vfsRootChangeCurrentDirectory(self->root, path);

if (self->root == NULL) {
  return CH_RET_ENOSYS;
}
if (buf == NULL) {
  return CH_RET_EINVAL;
}

return vfsRootGetCurrentDirectory(self->root, buf, size);

function.implementation:
#if VFS_CFG_ENABLE_DRV_ROOT == TRUE
if (np == &reserved_node) {
  return false;
}
#endif

return np != NULL;

if (!is_node(np)) {
  return CH_RET_EINVAL;
}
if ((np->vmt->addref != __ro_addref_impl) ||
    (np->vmt->release != __ro_release_impl)) {
  return CH_ENCODE_ERROR(ENOTSUP);
}

return CH_RET_SUCCESS;

chDbgCheckClassI();
chDbgAssert(np->references > 0U, "unreferenced node");

if (np->references == UINT_MAX) {
  return false;
}
np->references++;

return true;

vfs_node_c *np;
msg_t ret = CH_RET_EBADF;

if ((fd < 0) || ((size_t)fd >= self->size)) {
  return ret;
}

chSysLock();
np = self->nodes[fd];
if (is_node(np)) {
  if (retain_nodeI(np)) {
    *npp = np;
    ret = CH_RET_SUCCESS;
  }
  else {
    ret = CH_RET_EOVERFLOW;
  }
}
chSysUnlock();

return ret;
